        for (var pi = 0; pi < pts.length; pi++) {
          var segStart = pts[pi].t;
          var segEnd = (pi < pts.length - 1) ? pts[pi + 1].t : t1;
          var leftPct = total > 0 ? ((segStart - t0) / total) * 100 : 0;
          var widthPct = total > 0 ? ((segEnd - segStart) / total) * 100 : 100;
